const fse=require("fs-extra"),crypto=require("crypto"),keyConfig=require("./config/key.config");function getFileMd5(e){const t=fse.readFileSync(e),i=crypto.createHash("md5");return i.update(t),i.digest("hex")}async function isLocalFilePathSafe(e,t){if(!fse.existsSync(e))return!1;const i=getFileMd5(e),r=Buffer.from(t,"base64"),c=crypto.createVerify("RSA-SHA1");return c.update(i),!!c.verify(keyConfig.PUBLIKEY,r)}module.exports={getFileMd5:getFileMd5,isLocalFilePathSafe:isLocalFilePathSafe};